TASK
Map an iterable through asynchronous work with configured concurrency and ordered results.

PUBLIC CONTRACT
Module: await load('./index.js'); default export pMap, named exports pMapIterable and pMapSkip.
pMap(input, mapper, options?) returns a Promise of mapped values in input order. Inputs may be synchronous or asynchronous iterables and contain values or promises. Mapper receives (resolvedValue, inputIndex), and may return a value or promise. concurrency is an integer >=1 or Infinity (default Infinity). Empty input yields []. Returning pMapSkip omits that item. With stopOnError=true (default), an input or mapper rejection rejects the result; false waits for mapper work and aggregates mapper errors. A supplied AbortSignal cancels the operation using its reason.
pMapIterable(input, mapper, options?) returns an async iterable yielding mapped values in input order. concurrency bounds simultaneous mapper work; backpressure (default concurrency) bounds buffered results and must be >=concurrency. Mapper receives the resolved value and its input index. Mapper failures propagate to the consumer. pMapSkip omits an item.
Keep iteration, error propagation, ordering, and configured work limits consistent for ordinary values, promise inputs, and async sources.

SOURCE index.js
   1: export default async function pMap(
   2: 	iterable,
   3: 	mapper,
   4: 	{
   5: 		concurrency = Number.POSITIVE_INFINITY,
   6: 		stopOnError = true,
   7: 		signal,
   8: 	} = {},
   9: ) {
  10: 	return new Promise((resolve_, reject_) => {
  11: 		if (iterable[Symbol.iterator] === undefined && iterable[Symbol.asyncIterator] === undefined) {
  12: 			throw new TypeError(`Expected \`input\` to be either an \`Iterable\` or \`AsyncIterable\`, got (${typeof iterable})`);
  13: 		}
  14: 
  15: 		if (typeof mapper !== 'function') {
  16: 			throw new TypeError('Mapper function is required');
  17: 		}
  18: 
  19: 		if (!((Number.isSafeInteger(concurrency) && concurrency >= 1) || concurrency === Number.POSITIVE_INFINITY)) {
  20: 			throw new TypeError(`Expected \`concurrency\` to be an integer from 1 and up or \`Infinity\`, got \`${concurrency}\` (${typeof concurrency})`);
  21: 		}
  22: 
  23: 		const result = [];
  24: 		const errors = [];
  25: 		const skippedIndexesMap = new Map();
  26: 		let isRejected = false;
  27: 		let isResolved = false;
  28: 		let isIterableDone = false;
  29: 		let resolvingCount = 0;
  30: 		let currentIndex = 0;
  31: 		const iterator = iterable[Symbol.iterator] === undefined ? iterable[Symbol.asyncIterator]() : iterable[Symbol.iterator]();
  32: 
  33: 		const signalListener = () => {
  34: 			reject(signal.reason);
  35: 		};
  36: 
  37: 		const cleanup = () => {
  38: 			signal?.removeEventListener('abort', signalListener);
  39: 		};
  40: 
  41: 		const resolve = value => {
  42: 			resolve_(value);
  43: 			cleanup();
  44: 		};
  45: 
  46: 		const reject = reason => {
  47: 			isRejected = true;
  48: 			isResolved = true;
  49: 			reject_(reason);
  50: 			cleanup();
  51: 		};
  52: 
  53: 		if (signal) {
  54: 			if (signal.aborted) {
  55: 				reject(signal.reason);
  56: 			}
  57: 
  58: 			signal.addEventListener('abort', signalListener, {once: true});
  59: 		}
  60: 
  61: 		const next = async () => {
  62: 			if (isResolved) {
  63: 				return;
  64: 			}
  65: 
  66: 			const nextItem = await iterator.next();
  67: 
  68: 			const index = currentIndex;
  69: 			currentIndex++;
  70: 
  71: 			// Note: `iterator.next()` can be called many times in parallel.
  72: 			// This can cause multiple calls to this `next()` function to
  73: 			// receive a `nextItem` with `done === true`.
  74: 			// The shutdown logic that rejects/resolves must be protected
  75: 			// so it runs only one time as the `skippedIndex` logic is
  76: 			// non-idempotent.
  77: 			if (nextItem.done) {
  78: 				isIterableDone = true;
  79: 
  80: 				if (resolvingCount === 0 && !isResolved) {
  81: 					if (!stopOnError && errors.length > 0) {
  82: 						reject(new AggregateError(errors)); // eslint-disable-line unicorn/error-message
  83: 						return;
  84: 					}
  85: 
  86: 					isResolved = true;
  87: 
  88: 					if (skippedIndexesMap.size === 0) {
  89: 						resolve(result);
  90: 						return;
  91: 					}
  92: 
  93: 					const pureResult = [];
  94: 
  95: 					// Support multiple `pMapSkip`'s.
  96: 					for (const [index, value] of result.entries()) {
  97: 						if (skippedIndexesMap.get(index) === pMapSkip) {
  98: 							continue;
  99: 						}
 100: 
 101: 						pureResult.push(value);
 102: 					}
 103: 
 104: 					resolve(pureResult);
 105: 				}
 106: 
 107: 				return;
 108: 			}
 109: 
 110: 			resolvingCount++;
 111: 
 112: 			// Intentionally detached
 113: 			(async () => {
 114: 				try {
 115: 					const element = await nextItem.value;
 116: 
 117: 					if (isResolved) {
 118: 						return;
 119: 					}
 120: 
 121: 					const value = await mapper(element, index);
 122: 
 123: 					// Use Map to stage the index of the element.
 124: 					if (value === pMapSkip) {
 125: 						skippedIndexesMap.set(index, value);
 126: 					}
 127: 
 128: 					result[index] = value;
 129: 
 130: 					resolvingCount--;
 131: 					await next();
 132: 				} catch (error) {
 133: 					if (stopOnError) {
 134: 						reject(error);
 135: 					} else {
 136: 						errors.push(error);
 137: 						resolvingCount--;
 138: 
 139: 						// In that case we can't really continue regardless of `stopOnError` state
 140: 						// since an iterable is likely to continue throwing after it throws once.
 141: 						// If we continue calling `next()` indefinitely we will likely end up
 142: 						// in an infinite loop of failed iteration.
 143: 						try {
 144: 							await next();
 145: 						} catch (error) {
 146: 							reject(error);
 147: 						}
 148: 					}
 149: 				}
 150: 			})();
 151: 		};
 152: 
 153: 		// Create the concurrent runners in a detached (non-awaited)
 154: 		// promise. We need this so we can await the `next()` calls
 155: 		// to stop creating runners before hitting the concurrency limit
 156: 		// if the iterable has already been marked as done.
 157: 		// NOTE: We *must* do this for async iterators otherwise we'll spin up
 158: 		// infinite `next()` calls by default and never start the event loop.
 159: 		(async () => {
 160: 			for (let index = 0; index < concurrency; index++) {
 161: 				try {
 162: 					// eslint-disable-next-line no-await-in-loop
 163: 					await next();
 164: 				} catch (error) {
 165: 					reject(error);
 166: 					break;
 167: 				}
 168: 
 169: 				if (isIterableDone || isRejected) {
 170: 					break;
 171: 				}
 172: 			}
 173: 		})();
 174: 	});
 175: }
