 177: export function pMapIterable(
 178: 	iterable,
 179: 	mapper,
 180: 	{
 181: 		concurrency = Number.POSITIVE_INFINITY,
 182: 		backpressure = concurrency,
 183: 	} = {},
 184: ) {
 185: 	if (iterable[Symbol.iterator] === undefined && iterable[Symbol.asyncIterator] === undefined) {
 186: 		throw new TypeError(`Expected \`input\` to be either an \`Iterable\` or \`AsyncIterable\`, got (${typeof iterable})`);
 187: 	}
 188: 
 189: 	if (typeof mapper !== 'function') {
 190: 		throw new TypeError('Mapper function is required');
 191: 	}
 192: 
 193: 	if (!((Number.isSafeInteger(concurrency) && concurrency >= 1) || concurrency === Number.POSITIVE_INFINITY)) {
 194: 		throw new TypeError(`Expected \`concurrency\` to be an integer from 1 and up or \`Infinity\`, got \`${concurrency}\` (${typeof concurrency})`);
 195: 	}
 196: 
 197: 	if (!((Number.isSafeInteger(backpressure) && backpressure >= concurrency) || backpressure === Number.POSITIVE_INFINITY)) {
 198: 		throw new TypeError(`Expected \`backpressure\` to be an integer from \`concurrency\` (${concurrency}) and up or \`Infinity\`, got \`${backpressure}\` (${typeof backpressure})`);
 199: 	}
 200: 
 201: 	return {
 202: 		async * [Symbol.asyncIterator]() {
 203: 			const iterator = iterable[Symbol.asyncIterator] === undefined ? iterable[Symbol.iterator]() : iterable[Symbol.asyncIterator]();
 204: 
 205: 			const promises = [];
 206: 			let pendingPromisesCount = 0;
 207: 			let isDone = false;
 208: 			let index = 0;
 209: 
 210: 			function trySpawn() {
 211: 				if (isDone || !(pendingPromisesCount < concurrency && promises.length < backpressure)) {
 212: 					return;
 213: 				}
 214: 
 215: 				pendingPromisesCount++;
 216: 
 217: 				const promise = (async () => {
 218: 					const {done, value} = await iterator.next();
 219: 
 220: 					if (done) {
 221: 						pendingPromisesCount--;
 222: 						return {done: true};
 223: 					}
 224: 
 225: 					// Spawn if still below concurrency and backpressure limit
 226: 					trySpawn();
 227: 
 228: 					try {
 229: 						const returnValue = await mapper(await value, index++);
 230: 
 231: 						pendingPromisesCount--;
 232: 
 233: 						if (returnValue === pMapSkip) {
 234: 							const index = promises.indexOf(promise);
 235: 
 236: 							if (index > 0) {
 237: 								promises.splice(index, 1);
 238: 							}
 239: 						}
 240: 
 241: 						// Spawn if still below backpressure limit and just dropped below concurrency limit
 242: 						trySpawn();
 243: 
 244: 						return {done: false, value: returnValue};
 245: 					} catch (error) {
 246: 						pendingPromisesCount--;
 247: 						isDone = true;
 248: 						return {error};
 249: 					}
 250: 				})();
 251: 
 252: 				promises.push(promise);
 253: 			}
 254: 
 255: 			trySpawn();
 256: 
 257: 			while (promises.length > 0) {
 258: 				const {error, done, value} = await promises[0]; // eslint-disable-line no-await-in-loop
 259: 
 260: 				promises.shift();
 261: 
 262: 				if (error) {
 263: 					throw error;
 264: 				}
 265: 
 266: 				if (done) {
 267: 					return;
 268: 				}
 269: 
 270: 				// Spawn if just dropped below backpressure limit and below the concurrency limit
 271: 				trySpawn();
 272: 
 273: 				if (value === pMapSkip) {
 274: 					continue;
 275: 				}
 276: 
 277: 				yield value;
 278: 			}
 279: 		},
 280: 	};
 281: }
